 string release=Path.Combine(root,"release");Directory.CreateDirectory(release);File.WriteAllText(Path.Combine(release,"payload.exe"),"safe fixture, not executable");var manifest=new ServiceRelease{Version=37,Files=new[]{new ReleaseFile{Name="payload.exe",Hash=Data.Digest(File.ReadAllBytes(Path.Combine(release,"payload.exe")))}}};Check(ServiceRelease.Canonical(manifest).StartsWith("SARGON|37\npayload.exe|"));ServiceRelease.VerifyFiles(release,manifest);Check(true);var original=manifest.Files;manifest.Files=new[]{new ReleaseFile{Name="../outside",Hash=original[0].Hash}};Reject(()=>ServiceRelease.Canonical(manifest));manifest.Files=new[]{original[0],original[0]};Reject(()=>ServiceRelease.Canonical(manifest));manifest.Files=new[]{new ReleaseFile{Name="ž.exe",Hash=original[0].Hash}};Reject(()=>ServiceRelease.Canonical(manifest));manifest.Files=original;
